// Generated by pnpm docs:api. Edit the source specimen instead.
// oxlint-disable no-unused-vars -- the scoped specimen preserves hook ordering from its source
import { useCallback, useState } from "react";
import { SectionPage, Specimen } from "glass-ux-docs-kit/react";
import { FilterGallery, type FilterGalleryItem } from "glass-ux-image/panels/filter-gallery";
import { useImageEditor, useSessionState } from "glass-ux-image/react";

const photo = `${import.meta.env.BASE_URL}sample.png`;
const effect = (filter: string, params: Record<string, unknown>) => [
  { id: filter, filter, params, strength: 1 },
];
const looks: FilterGalleryItem[] = [
  { id: "original", label: "Original", effects: [] },
  { id: "sepia", label: "Sepia", effects: effect("sepia", { amount: 1 }) },
  { id: "faded", label: "Faded colours", effects: effect("faded", { amount: 1 }) },
  { id: "vignette", label: "Vignette", effects: effect("vignette", { amount: 1, radius: 2 }) },
  {
    id: "bloom",
    label: "Bloom",
    effects: effect("bloom", { amount: 1, radius: 2, threshold: 0.7 }),
  },
  {
    id: "pencil",
    label: "Pencil sketch",
    effects: effect("pencil-sketch", { amount: 1, radius: 2 }),
  },
  { id: "posterise", label: "Posterise", effects: effect("posterise", { amount: 1, levels: 6 }) },
  { id: "pixelate", label: "Pixelate", effects: effect("pixelate", { amount: 1, size: 12 }) },
];

function FilterGallerySample() {
  // Thumbnails render from a small preview of the open picture, in a worker.
  const editor = useImageEditor({ source: photo });
  const { status, size } = useSessionState(editor);
  const preview = useCallback(() => editor.readPreview(320), [editor]);
  const [chosen, setChosen] = useState<string | null>(null);
  return (
    <div className="flex w-full max-w-2xl flex-col gap-3">
      <FilterGallery
        items={looks}
        source={status === "ready" ? preview : null}
        documentWidth={size?.width}
        disabled={status !== "ready"}
        value={chosen}
        onValueChange={setChosen}
      />
      <output aria-live="polite" className="type-caption text-fg-muted">
        {chosen
          ? `Chosen: ${looks.find((look) => look.id === chosen)?.label}`
          : "Nothing chosen yet"}
      </output>
    </div>
  );
}

export default function Section() {
  return (
    <SectionPage>
      <Specimen
        title="Before and after"
        description="Each candidate rendered on a small copy of the photo, in a worker. Choosing one only reports it, so a host can preview, confirm or add it to a stack."
        specimenKey="filter-gallery:default:0"
      >
        <div data-live-demo="filter-gallery" className="w-full">
          <FilterGallerySample />
        </div>
      </Specimen>
    </SectionPage>
  );
}
